-- {"check_type":"column_present", "table_schema":"gold_con", "table_name":"dim_mortgage_transaction", "column_name":"IS_FINANCIAL_TRANSACTION"}
MERGE INTO {catalog_name}.gold_con.dim_mortgage_transaction AS dmt
USING (SELECT DISTINCT a.TYPE, CAST((CASE WHEN a.TYPE IN ('DISBURSMENT', 'REPAYMENT', 'FEE', 'FEE_APPLIED', 'PENALTY_APPLIED', 'REPAYMENT_ADJUSTMENT', 'FEE_ADJUSTMENT', 'PENALTY_ADJUSTMENT', 'DEFERRED_INTEREST_APPLIED', 'DEFERRED_INTEREST_APPLIED_ADJUSTMENT', 'DEFERRED_INTEREST_PAID', 'DEFERRED_INTEREST_PAID_ADJUSTMENT', 'DISBURSEMENT_ADJUSTMENT', 'FEE_CHARGED', 'FEE_REDUCTION_ADJUSTMENT', 'FEES_DUE_REDUCED', 'INTEREST_APPLIED', 'INTEREST_APPLIED_ADJUSTMENT', 'INTEREST_DUE_REDUCED', 'INTEREST_REDUCTION_ADJUSTMENT', 'PENALTIES_DUE_REDUCED', 'PENALTY_REDUCTION_ADJUSTMENT', 'TRANSFER', 'TRANSFER_ADJUSTMENT', 'WRITE_OFF', 'WRITE_OFF_ADJUSTMENT', 'WITHDRAWAL_REDRAW', 'FEE_CAPITALISED', 'FEE_CAPITALISED_ADJUSTMENT', 'PAYMENT_MADE', 'REDRAW_REPAYMENT', 'PRINCIPAL_OVERPAYMENT', 'PRINCIPAL_OVERPAYMENT_ADJUSTMENT', 'WITHDRAWAL_REDRAW_ADJUSTMENT', 'IBF_INTEREST_APPLIED_ADJUSTMENT', 'REDUCE_BALANCE', 'IBF_INTEREST_APPLIED' ) THEN 'Yes' ELSE 'No' END) AS STRING) AS IS_FINANCIAL_TRANSACTION
      FROM {catalog_name}.silver_con.mambu_loan_transaction a) x
ON dmt.TRANSACTION_TYPE = COALESCE(INITCAP(REPLACE(x.TYPE,'_',' ')), 'Unknown')
AND dmt.ROW_IS_CURRENT = 1
WHEN MATCHED THEN
  UPDATE SET dmt.IS_FINANCIAL_TRANSACTION = x.IS_FINANCIAL_TRANSACTION